/** Compile the browser OpenUI language into the versioned cross-surface contract. */
export function compileOpenUISourceToSharedDocument(source: string, options: CompileSharedOpenUIOptions): UiDocument {
	const result = parser.parse(source);
	if (!result.root || result.root.typeName !== "LearningSurface") throw new Error("OpenUI source has no LearningSurface root.");
	if (result.meta.incomplete || result.root.partial) throw new Error("OpenUI source is incomplete.");
	if (result.meta.errors.length || result.meta.unresolved.length) throw new Error("OpenUI source contains invalid or unresolved components.");
	const content = result.root.props.content;
	if (!Array.isArray(content) || !content.every((entry) => record(entry).type === "element")) throw new Error("OpenUI LearningSurface content is invalid.");
	const at = options.updatedAt ?? options.createdAt ?? new Date().toISOString();
	const document: UiDocument = {
		schemaVersion: UI_CONTRACT_VERSION,
		id: contractId(options.documentId, "openui-document"),
		revision: options.revision ?? 0,
		lifecycle: "ready",
		supportedSurfaces: ["web", "desktop", "mobile", "terminal"],
		...(optionalText(result.root.props.title) ? { title: text(result.root.props.title) } : {}),
		...(optionalText(result.root.props.description) ? { description: text(result.root.props.description) } : {}),
		nodes: content.flatMap((entry, index) => mapElement(entry as ElementNode, index)),
		createdAt: options.createdAt ?? at,
		updatedAt: at,
	};
	if (!validateUiDocument(document)) throw new Error("Compiled OpenUI document does not satisfy the shared learner contract.");
	return document;
}
