224				setState({ version: 1, document: dispatched.document, journal: dispatched.journal });
225				setActionError(null);
226				if (!dispatched.replayed) {
227					hostAction?.({
228						kind: "canonical",
229						type: dispatched.action.type,
230						humanFriendlyMessage: event.humanFriendlyMessage,
231						params: canonicalActionParams(dispatched.action),
232						document: {
233							...metadata,
234							id: dispatched.sourceDocument.id,
235							revision: dispatched.sourceDocument.revision,
236						},
237						action: dispatched.action,
238						sourceDocument: dispatched.sourceDocument,
239						receipt: dispatched.receipt,
240					});
241				}
242				return true;
243			} catch (cause) {
244				setActionError(cause instanceof Error
245					? `This interaction was not saved: ${cause.message} Your entered work is still here; retry when ready.`
246					: "This interaction was not saved. Your entered work is still here; retry when ready.");
247				return false;
248			}
249		}, [actionStorage, hostAction, metadata, state.document]);
250	
251		return <>
252			<SharedUiDocumentRenderer
253				document={state.document}
254				receipts={state.journal.receipts}
255				onAction={handleSharedAction}
256			/>
257			{actionError ? <div className={css({ marginBlock: "0.75rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">{actionError}</div> : null}
258		</>;
259	}
130			}
131			if (character === "\n" && stack.length === 0) lastCommit = index + 1;
132		}
133	
134		return program.slice(0, lastCommit).trimEnd();
135	}
