137	/**
138	 * Split assistant text into Markdown and OpenUI programs.
139	 *
140	 * An opening fence produces a segment immediately, but only whole top-level
141	 * statements are committed to the renderer. Existing Markdown and legacy
142	 * `<keating-*>` tags remain untouched in text segments.
143	 */
144	export function parseOpenUIMessageSegments(text: string, documentScope = ""): OpenUIMessageSegment[] {
145		const segments: OpenUIMessageSegment[] = [];
146		let cursor = 0;
147		OPENUI_FENCE.lastIndex = 0;
148		let match: RegExpExecArray | null;
149	
150		while ((match = OPENUI_FENCE.exec(text)) !== null) {
151			if (match.index > cursor) {
152				segments.push({ type: "text", content: text.slice(cursor, match.index) });
153			}
154	
155			const bodyStart = OPENUI_FENCE.lastIndex;
156			const closing = findClosingFence(text, bodyStart);
157			const bodyEnd = closing?.index ?? text.length;
158			const rawProgram = text.slice(bodyStart, bodyEnd);
159			const metadata = parseMetadata(match[1], rawProgram, match.index, documentScope);
160			const trimmed = rawProgram.trim();
161			if (trimmed.startsWith("{")) {
162				let document: UiDocument | undefined;
163				let error: string | undefined;
164				if (closing) {
165					try {
166						const candidate: unknown = JSON.parse(trimmed);
167						if (!validateUiDocument(candidate)) throw new Error("The OpenUI JSON document does not satisfy the learner contract.");
168						const scoped = { ...candidate, id: metadata.id, revision: metadata.revision };
169						if (!validateUiDocument(scoped)) throw new Error("The scoped OpenUI JSON document does not satisfy the learner contract.");
170						document = scoped;
171					} catch (cause) {
172						error = cause instanceof Error ? cause.message : "The OpenUI JSON document is invalid.";
173					}
174				}
175				segments.push({ type: "openui", format: "document", program: "", rawProgram, complete: closing !== null, ...(document ? { document } : {}), ...(error ? { error } : {}), metadata });
176			} else {
177				segments.push({
178					type: "openui",
179					format: "source",
180					program: committedOpenUIProgram(rawProgram, closing !== null),
181					rawProgram,
182					complete: closing !== null,
183					metadata,
184				});
185			}
186	
187			if (!closing) {
188				cursor = text.length;
189				break;
190			}
191			cursor = closing.end;
192			OPENUI_FENCE.lastIndex = cursor;
193		}
194	
195		if (cursor < text.length) segments.push({ type: "text", content: text.slice(cursor) });
196		if (segments.length === 0) segments.push({ type: "text", content: text });
197		return segments;
198	}
