200	/** Remove OpenUI source from text copied from an assistant message. */
201	export function stripOpenUIPrograms(text: string): string {
202		return parseOpenUIMessageSegments(text)
203			.filter((segment): segment is Extract<OpenUIMessageSegment, { type: "text" }> => segment.type === "text")
204			.map((segment) => segment.content)
205			.join("")
