 59	function Question({ node, receipt, disabled, onAction }: { node: UiQuestion; receipt?: UiActionReceipt; disabled: boolean; onAction?: (event: SharedUiActionEvent) => boolean }) {
 60		const savedAction = receipt?.action;
 61		const savedAnswer = savedAction?.type === "submit-answer" ? savedAction.answer : undefined;
 62		const savedRows = Array.isArray(savedAnswer) && savedAnswer.every((entry) => typeof entry === "object")
 63			? savedAnswer as Array<{ item: string; optionId: string; reason?: string }>
 64			: undefined;
 65		const [answer, setAnswer] = useState(() => typeof savedAnswer === "string" ? savedAnswer : "");
 66		const [selected, setSelected] = useState<string[]>(() => savedAction?.type === "choose-option" ? [...savedAction.optionIds] : []);
 67		const [rowSelections, setRowSelections] = useState<string[]>(() => node.items?.map((item) => savedRows?.find((row) => row.item === item)?.optionId ?? "") ?? []);
 68		const [rowReasons, setRowReasons] = useState<string[]>(() => node.items?.map((item) => savedRows?.find((row) => row.item === item)?.reason ?? "") ?? []);
 69		const blankCount = node.blanks?.length ?? (node.prompt.match(/_{3,}|\{\{blank\}\}/g)?.length ?? 0);
 70		const [blankAnswers, setBlankAnswers] = useState<string[]>(() => Array.isArray(savedAnswer) && savedAnswer.every((entry) => typeof entry === "string")
 71			? [...savedAnswer]
 72			: Array.from({ length: blankCount }, () => ""));
 73		const multiple = node.multiSelect || node.kind === "multi_select";
