 75		const blanks = node.kind === "blanks" || node.kind === "fill_in";
 76		const payload = rows
 77			? (node.items ?? []).map((item, index) => ({ item, optionId: rowSelections[index] ?? "", ...(node.requireReasons ? { reason: rowReasons[index] ?? "" } : {}) }))
