 91			<legend className={css({ fontWeight: 650 })}>{node.header ?? node.prompt}</legend>
 92			{node.header ? <p>{node.prompt}</p> : null}
 93			{rows ? <div className={css({ display: "grid", gap: "0.75rem" })}>{node.items?.map((item, rowIndex) => <div key={`${node.id}-${rowIndex}`} className={css({ display: "grid", gap: "0.375rem", border: "1px solid var(--border)", borderRadius: "0.5rem", padding: "0.625rem" })}>
 94				<strong>{item}</strong>
 95				<select disabled={disabled || completed} className={input} aria-label={`${node.choiceLabel ?? "Choice"} for ${item}`} value={rowSelections[rowIndex]} onChange={(event) => setRowSelections((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))}><option value="">Select…</option>{node.choices?.map((choice) => <option key={choice.id} value={choice.id} disabled={node.kind === "matching" && node.uniqueMatches !== false && rowSelections.some((selected, index) => index !== rowIndex && selected === choice.id)}>{choice.label}</option>)}</select>
