 78	function isStoredState(value: unknown): value is StoredSharedUiActionState {
 79		if (!value || typeof value !== "object" || Array.isArray(value)) return false;
 80		const candidate = value as Partial<StoredSharedUiActionState>;
 81		return candidate.version === 1
 82			&& validateUiDocument(candidate.document)
 83			&& validateUiActionJournal(candidate.journal)
 84			&& candidate.document.id === candidate.journal.documentId;
 85	}
