 87	/**
 88	 * Load only a strictly validated result newer than the message snapshot. A
 89	 * same-revision content mismatch means the model supplied a competing snapshot,
 90	 * so the message remains authoritative and the stale local journal is ignored.
 91	 */
 92	export function loadSharedUiActionState(
 93		storage: Pick<StorageLike, "getItem"> | null,
 94		sourceDocument: UiDocument,
 95	): StoredSharedUiActionState {
 96		const fallback = {
 97			version: 1 as const,
 98			document: structuredClone(sourceDocument),
 99			journal: emptySharedUiActionJournal(sourceDocument.id),
100		};
101		if (!storage || !validateUiDocument(sourceDocument)) return fallback;
102		try {
103			const raw = storage.getItem(sharedUiActionStateKey(sourceDocument.id));
104			if (!raw) return fallback;
105			const candidate: unknown = JSON.parse(raw);
106			if (!isStoredState(candidate) || candidate.document.id !== sourceDocument.id) return fallback;
107			if (candidate.document.revision > sourceDocument.revision) return structuredClone(candidate);
108			if (candidate.document.revision === sourceDocument.revision
109				&& stableJson(candidate.document) === stableJson(sourceDocument)) return structuredClone(candidate);
110			return fallback;
111		} catch {
112			return fallback;
113		}
114	}
