116	export function createSharedUiAction(document: UiDocument, intent: SharedUiActionIntent): UiAction {
117		const idempotencyKey = `web-ui-${hashText(stableJson({
118			documentId: document.id,
119			documentRevision: document.revision,
120			intent,
121		}))}`;
122		const action = {
123			...intent,
124			schemaVersion: UI_CONTRACT_VERSION,
125			documentId: document.id,
126			documentRevision: document.revision,
127			idempotencyKey,
128		} as UiAction;
129		if (!validateUiAction(action)) throw new Error("The OpenUI action is invalid.");
130		return action;
131	}
