149	function applyActionToNodes(nodes: readonly UiDocumentNode[], action: UiAction): UiDocumentNode[] {
150		return nodes.map((node) => {
151			if (action.type === "complete-goal-step" && node.type === "goal" && node.id === action.nodeId) {
152				const steps = node.steps.map((step) => step.id === action.stepId
153					? { ...step, status: "done" as const }
154					: step);
155				return {
156					...node,
157					steps,
158					status: steps.every((step) => step.status === "done") ? "completed" as const : node.status,
159				};
160			}
161			if (action.type === "complete-plan-item" && node.type === "study-plan" && node.id === action.nodeId && node.items) {
162				return { ...node, items: updatePlanItems(node.items, action.itemId, action.completed) };
163			}
164			if (action.type === "update-notes" && node.type === "notes" && node.id === action.nodeId) {
165				return { ...node, value: action.value };
166			}
167			return node;
168		});
