175			lifecycle: action.type === "retry" ? "ready" : source.lifecycle,
176			nodes: applyActionToNodes(source.nodes, action),
177			updatedAt: now,
178		};
179		if (!validateUiDocument(document)) throw new Error("The OpenUI action produced an invalid document.");
